return (function(frame,durationFrames,props){
const t = frame / fps, D = durationFrames / fps;
const C = {mint:'#64f5d2', blue:'#53bfff', purple:'#a399ff', amber:'#ffc775'};
const clamp = x => Math.max(0, Math.min(1, x));
const smooth = x => { x = clamp(x); return x*x*(3-2*x); };
const mix = (a,b,p) => a+(b-a)*clamp(p);
const enter = (at=0,d=.65) => 1-Math.pow(1-clamp((t-at)/d),3);
const esc = s => String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
const img = (id,style='') => `<img src="${assets[id]}" style="${style}"/>`;
const pos = (x,y,w,h,html,style='') => `<div style="position:absolute;left:${x}px;top:${y}px;width:${w}px;height:${h}px;${style}">${html}</div>`;
const photo = (id,style='') => img(id,`width:100%;height:100%;object-fit:cover;${style}`);
const reveal = (html,at=0,d=.65) => `<div style="opacity:${enter(at,d)};transform:translateY(${40*(1-enter(at,d))}px)">${html}</div>`;
const label = s => `<div class="eyebrow">${s}</div>`;
const title = (a,b) => `${label(a)}<h1>${b}</h1>`;
const ring = (cx,cy,r,clock=t) => `<svg class="svg" viewBox="0 0 1920 1080">${[1,.8,1.15].map((k,i)=>`<ellipse cx="${cx}" cy="${cy}" rx="${r*k}" ry="${r*k*.43}" fill="none" stroke="${i===1?C.mint:C.blue}" stroke-width="${i===1?2:1}" stroke-dasharray="${i===1?'7 9 60 18':'160 15 6 20'}" stroke-dashoffset="${-clock*35}" opacity="${i===1?.65:.25}" transform="rotate(${(i-1)*38+clock*(i%2?-12:8)},${cx},${cy})"/>`).join('')}</svg>`;
const dataPath = (d,at=0,color=C.mint,width=3,clock=t) => `<path d="${d}" fill="none" stroke="${color}" stroke-width="1.2" opacity=".22"/><path d="${d}" fill="none" stroke="${color}" stroke-width="${width}" pathLength="200" stroke-dasharray="${200*enter(at,.7)} 200" opacity=".65"/><path d="${d}" fill="none" stroke="#d7fff9" stroke-width="${width+1}" pathLength="200" stroke-dasharray="9 191" stroke-dashoffset="${-((clock*75+at*31)%200)}" stroke-linecap="round"/>`;
const core = (cx,cy,r,clock=t) => {
  const pts = Array.from({length:64},(_,i)=>{
    const ph=Math.acos(1-2*(i+.5)/64),th=i*2.399963+clock*.65;
    const x=Math.sin(ph)*Math.cos(th),y=Math.cos(ph),z=Math.sin(ph)*Math.sin(th);
    return {x:cx+x*r*(1+z*.15),y:cy+y*r*(1+z*.15),z};
  });
  return `<svg class="svg" viewBox="0 0 1920 1080"><defs><radialGradient id="core-halo"><stop stop-color="#4f7bff" stop-opacity=".38"/><stop offset="1" stop-color="#33dedd" stop-opacity="0"/></radialGradient></defs><circle cx="${cx}" cy="${cy}" r="${r*1.8}" fill="url(#core-halo)"/>${pts.map((a,i)=>pts.slice(i+1).filter(b=>Math.hypot(a.x-b.x,a.y-b.y)<r*.43).map(b=>`<path d="M${a.x} ${a.y}L${b.x} ${b.y}" stroke="${C.blue}" stroke-width="1.3" opacity="${.16+.16*(a.z+1)/2}"/>`).join('')).join('')}${pts.map((a,i)=>`<circle cx="${a.x}" cy="${a.y}" r="${3+(a.z+1)*2}" fill="${i%4?C.mint:C.purple}" opacity="${.35+.3*(a.z+1)}"/>`).join('')}</svg>`;
};
const metric = (value,progress=enter(.7,1.2)) => {
  if(!/^[0-9.]+%$/.test(value)) return value;
  const n=parseFloat(value),places=(value.split('.')[1]||'').replace('%','').length;
  return (n*clamp(progress)).toFixed(places)+'%';
};
const subtitle = () => {
  const parts=props.narration?.match(/[^，。；！？]+[，。；！？]?/g)||[];
  const vs=props.voiceSeconds||D-1.2;
  if(!parts.length||t<.5||t>vs+.5) return '';
  let n=0,selected='';const p=clamp((t-.5)/vs),length=parts.join('').length;
  for(const part of parts){n+=part.length;if(p<=n/length){selected=part.replace(/[，。；]$/,'');break;}}
  return `<div class="subtitle">${selected}</div>`;
};
const particles = `<svg class="svg" viewBox="0 0 1920 1080">${Array.from({length:44},(_,i)=>{
  const x=(i*317.7+Math.sin(t*.3+i)*60)%1920,y=(i*171.3-t*(13+i%5)+10800)%1080;
  return `<circle cx="${x}" cy="${y}" r="${i%4===0?2.2:1.1}" fill="${i%3?C.blue:C.mint}" opacity="${.13+.22*(1+Math.sin(t*2+i))/2}"/>`;
}).join('')}</svg>`;
const grid = `<div class="floor" style="transform:perspective(650px) rotateX(65deg) translateY(${t*15%60}px)"></div>`;
const shell = (body,options={}) => {
  const sweep=clamp(t/.43),out=clamp((D-t)/.16);
  return `${css}<div class="film" style="opacity:${out}">${grid}${particles}${body}<div class="topbar"><span>${props.chapter}</span>${img('logo','width:205px;height:65px;object-fit:contain')}</div>${options.noTitle?'':`<div class="section-title">${props.title}</div>`}${subtitle()}<div class="bottom"><span>同算时代科技（苏州）有限公司</span><span>${options.note||'AI 智控节能优化方案'}</span></div><div class="progress" style="width:${((props.startSeconds||0)+t)/(props.totalSeconds||210)*100}%"></div>${t<.43?`<div style="position:absolute;inset:0;pointer-events:none;background:linear-gradient(110deg,transparent 44%,#64ffe755 49%,#b4fff790 50%,transparent 54%);transform:translateX(${mix(-2100,2100,sweep)}px)"></div>`:''}</div>`;
};
const css = `<style>
*{box-sizing:border-box}body{margin:0;background:#030b18}
.film{width:1920px;height:1080px;position:relative;overflow:hidden;color:#f1fbff;background:radial-gradient(ellipse at 70% 30%,#14365c,transparent 65%),radial-gradient(ellipse at 5% 85%,#073c3d,transparent 65%),#030b18;font-family:-apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft YaHei",sans-serif}
.svg{position:absolute;inset:0;width:1920px;height:1080px;pointer-events:none}
.topbar{position:absolute;top:30px;left:80px;right:80px;display:flex;justify-content:space-between;align-items:center;height:65px;z-index:50}
.topbar>span{font-size:19px;color:#7bb8cc;letter-spacing:5px}
.section-title{position:absolute;left:80px;top:130px;font-size:42px;font-weight:600;z-index:35}
.floor{position:absolute;inset:580px -500px -500px;background-image:linear-gradient(#4a90ac26 1px,transparent 1px),linear-gradient(90deg,#4a90ac26 1px,transparent 1px);background-size:100px 60px;transform-origin:center top;mask-image:linear-gradient(transparent,#000)}
.eyebrow{font-size:21px;letter-spacing:5px;color:#64f5d2;line-height:1.6}
h1{font-size:98px;line-height:1.18;margin:20px 0 30px;font-weight:600;letter-spacing:2px}
h2{font-size:64px;line-height:1.25;margin:20px 0;font-weight:600}h3{margin:12px 0;font-size:31px;font-weight:500}
p{margin:0}.accent{color:#64f5d2}.copy{font-size:29px;line-height:1.7;color:#bddeed}.small{font-size:22px;line-height:1.65;color:#8cb3c7}
.panel{border:1px solid #64c9e445;background:linear-gradient(135deg,#1a4d6a80,#041528d9);border-radius:8px;box-shadow:0 20px 60px #0004}
.number{font-size:100px;line-height:1;font-weight:600;color:#6df5d8;letter-spacing:-3px;font-variant-numeric:tabular-nums}
.subtitle{position:absolute;bottom:72px;left:200px;right:200px;font-size:29px;line-height:1.5;text-align:center;color:#fff;text-shadow:0 2px 9px #000;background:linear-gradient(90deg,transparent,#030d1cd9 18%,#030d1cd9 82%,transparent);padding:12px 25px;z-index:55}
.bottom{position:absolute;bottom:26px;left:80px;right:80px;display:flex;justify-content:space-between;font-size:15px;letter-spacing:2px;color:#779db6;z-index:50}
.progress{position:absolute;bottom:0;left:0;height:3px;background:linear-gradient(90deg,#3972ff,#64f5d2)}
.plate{background:#fff;border:1px solid #a0e8ed;box-shadow:0 25px 70px #0007;overflow:hidden}
</style>`;

// Authored cooling-station illustration. Numbers and equipment motion illustrate control.
const fan = (cx,cy,r,clock,speed=1,color=C.mint) => `<g transform="translate(${cx} ${cy}) scale(1 .48)"><circle r="${r}" fill="#071626" stroke="#61baca" stroke-width="3"/><circle r="${r*.84}" fill="none" stroke="#336077" stroke-width="2"/>${[0,120,240].map(a=>`<path d="M0 0Q${r*.6} ${-r*.95} ${r*.76} ${-r*.2}Q${r*.8} ${r*.25} 0 0" fill="${color}" fill-opacity=".75" transform="rotate(${a+clock*speed*180})"/>`).join('')}<circle r="${r*.15}" fill="#d4fff5"/></g>`;
const rotor = (cx,cy,r,clock,speed=1) => `<g transform="translate(${cx} ${cy}) rotate(${clock*speed*160})"><circle r="${r}" fill="#0a2239" stroke="#64dcdf" stroke-width="3"/>${[0,60,120,180,240,300].map(a=>`<path d="M0 -5L${r*.7} -${r*.3}L${r*.6} ${r*.2}Z" fill="#5de4e4" transform="rotate(${a})"/>`).join('')}<circle r="${r*.17}" fill="#edffff"/></g>`;
const valve = (cx,cy,clock) => {
  const open=.3+.6*(.5+.5*Math.sin(clock*.9));
  return `<g transform="translate(${cx} ${cy})"><path d="M-25 -17L25 17V-17L-25 17Z" fill="#1b596e" stroke="#78e5e0" stroke-width="2"/><path d="M0 -18V-45" stroke="#7ed2e9" stroke-width="5"/><g transform="translate(0 -48) rotate(${open*100})"><ellipse rx="23" ry="9" fill="none" stroke="#7bf5d7" stroke-width="5"/><path d="M-22 0H22" stroke="#7bf5d7" stroke-width="3"/></g></g>`;
};
const plant = (clock=t,mode='running',focus=-1) => {
  const load=.58+.24*Math.sin(clock*.67),speed=.6+load;
  const towers=Array.from({length:4},(_,i)=>{
    const x=190+i*255,y=125,active=focus<0||focus===0;
    return `<g opacity="${active?1:.35}"><path d="M${x-58} ${y}L${x+74} ${y+7}V${y+157}L${x-58} ${y+145}Z" fill="url(#plant-metal)" stroke="#608cac" stroke-width="2"/><path d="M${x+74} ${y+7}L${x+110} ${y-15}V${y+135}L${x+74} ${y+157}Z" fill="#15374d" stroke="#40738c" stroke-width="2"/><path d="M${x-58} ${y}L${x-20} ${y-26}L${x+110} ${y-15}L${x+74} ${y+7}Z" fill="#25516a" stroke="#70b8cd" stroke-width="2"/>${Array.from({length:7},(_,j)=>`<path d="M${x-43} ${y+45+j*12}L${x+58} ${y+53+j*12}" stroke="#86a8bb" stroke-width="2" opacity=".4"/>`).join('')}${fan(x+25,y-9,58,clock+i*.8,speed)}<path d="M${x+85} ${y+140}V${y+175}" stroke="#63e6db" stroke-width="13"/><text x="${x-14}" y="${y+93}" fill="#b9e5ee" font-size="21">CT-${i+1}</text>${[0,1,2].map(j=>{const p=(clock*.55+i*.2+j/3)%1;return `<path d="M${x-20+j*35} ${y-50-p*65}q15 -20 0 -35" fill="none" stroke="#87eaf2" stroke-width="2" opacity="${(1-p)*.35}"/>`}).join('')}</g>`;
  }).join('');
  const machines=Array.from({length:3},(_,i)=>{
    const x=280+i*345,y=420,active=focus<0||focus===1;
    return `<g opacity="${active?1:.35}"><path d="M${x-85} ${y-50}L${x+90} ${y-50}L${x+133} ${y-80}L${x-42} ${y-80}Z" fill="#38647c" stroke="#73b7d0"/><path d="M${x+90} ${y-50}L${x+133} ${y-80}V${y+40}L${x+90} ${y+70}Z" fill="#0b263e" stroke="#477d98"/><rect x="${x-85}" y="${y-50}" width="175" height="120" rx="8" fill="url(#plant-metal)" stroke="#65b9d1" stroke-width="2"/><rect x="${x-60}" y="${y-30}" width="75" height="48" rx="4" fill="#092136" stroke="#466d87"/><path d="M${x-48} ${y-10}h13l8 -7 8 15 9 -7h12" fill="none" stroke="#68ffd2" stroke-width="2"/><text x="${x-57}" y="${y+43}" fill="#d4f5ff" font-size="19">CH-${i+1}</text>${rotor(x+57,y+12,23,clock+i*.4,speed*.7)}<path d="M${x-60} ${y+72}V${y+94}M${x+62} ${y+72}V${y+94}" stroke="#41667f" stroke-width="10"/><circle cx="${x-70}" cy="${y+56}" r="4" fill="${clock%2>.1?C.mint:'#32556a'}"/></g>`;
  }).join('');
  const pumps=Array.from({length:4},(_,i)=>{
    const x=320+i*218,y=625,active=focus<0||focus===2;
    return `<g opacity="${active?1:.35}"><path d="M${x-25} ${y+32}v18h86v-18" fill="#284b64" stroke="#587d94"/><rect x="${x+10}" y="${y-22}" width="65" height="47" rx="7" fill="#255574" stroke="#61a1ba"/>${rotor(x,y,32,clock+i*.3,speed*1.4)}<path d="M${x+76} ${y-15}v32" stroke="#5287a3" stroke-width="5"/>${valve(x+108,y+4,clock+i)}</g>`;
  }).join('');
  const paths=[
    ['M275 300H1040V360H1085V565H1160',C.mint],
    ['M250 320H1070V342H1115V590H1160',C.blue],
    ['M190 300V283',C.mint],['M445 300V283',C.mint],
    ['M700 300V283',C.mint],['M955 300V283',C.mint],
    ['M195 520H1075',C.blue],['M280 515V540H1010',C.mint],
    ['M235 520V555H290V625',C.blue],['M550 520V570H508V625',C.blue],
    ['M900 520V580H726V625',C.blue],['M1075 520V595H944V625',C.blue],
    ['M425 629V700H1160V565',C.mint],['M643 629V700',C.mint],
    ['M861 629V700',C.mint],['M1079 629V700',C.mint]
  ];
  return `<svg viewBox="0 0 1400 760" style="width:100%;height:100%;overflow:visible"><defs><linearGradient id="plant-metal" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#496c87"/><stop offset=".55" stop-color="#27445e"/><stop offset="1" stop-color="#112c44"/></linearGradient><linearGradient id="plant-base"><stop stop-color="#16405b" stop-opacity=".65"/><stop offset="1" stop-color="#062132" stop-opacity=".2"/></linearGradient></defs><path d="M20 525L260 75H1230L1375 650L1100 745H195Z" fill="url(#plant-base)" stroke="#4daec13b"/>${Array.from({length:11},(_,i)=>`<path d="M${90+i*113} 100L${30+i*123} 700" stroke="#458da2" stroke-opacity=".12"/>`).join('')}${paths.map(([d,c],i)=>`<path d="${d}" fill="none" stroke="#051626" stroke-width="19" stroke-linecap="round" stroke-linejoin="round"/><path d="${d}" fill="none" stroke="${c}" stroke-width="8" stroke-opacity=".45" stroke-linecap="round" stroke-linejoin="round"/><path d="${d}" fill="none" stroke="${c}" stroke-width="3" pathLength="240" stroke-dasharray="14 18" stroke-dashoffset="${-clock*85-i*17}" stroke-linejoin="round"/>`).join('')}${towers}${machines}${pumps}<text x="1180" y="570" fill="#63e9d9" font-size="23">末端负荷</text><text x="1180" y="604" fill="#8bb5ca" font-size="21">${Math.round(load*100)}%</text></svg>`;
};
const lineChart = (clock=t,mode='load',progress=1) => {
  const values=Array.from({length:81},(_,i)=>{
    const x=i/80;
    const y=mode==='load'?140-62*Math.sin(x*10+clock*.75)-20*Math.sin(x*24-clock):mode==='stability'?130+(1-x)*70*Math.sin(x*35+clock*.6):60+x*105+8*Math.sin(x*12+clock*.5);
    return [x*720,y];
  });
  const count=Math.max(2,Math.ceil(progress*values.length)),pts=values.slice(0,count).map(([x,y])=>`${x},${y}`).join(' '),last=values[count-1];
  return `<svg viewBox="0 0 760 280" style="width:100%;height:100%"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#3de5c9" stop-opacity=".3"/><stop offset="1" stop-color="#3de5c9" stop-opacity="0"/></linearGradient></defs>${[45,95,145,195,245].map(y=>`<path d="M0 ${y}H740" stroke="#5a92b2" opacity=".2"/>`).join('')}<polygon points="0,260 ${pts} ${last[0]},260" fill="url(#chart-fill)"/><polyline points="${pts}" fill="none" stroke="#64f5d2" stroke-width="4"/><circle cx="${last[0]}" cy="${last[1]}" r="7" fill="#d3fff2"/><path d="M${clock*75%720} 20V260" stroke="#b7f7ff" stroke-dasharray="3 8" opacity=".5"/></svg>`;
};

// Motion belongs to each supplied picture: reveal, scan and highlight keep it legible.
const picturePanel = (key,x,y,w,h,options={}) => {
  const clock=options.clock===undefined?t:options.clock;
  const p=1-Math.pow(1-clamp(clock/.38),3);
  const scale=(options.scale||1)*(1+.012*Math.sin(Math.max(0,clock)*.65));
  const white=options.white!==false;
  return pos(x,y,w,h,`<div style="position:relative;width:100%;height:100%;overflow:hidden;background:${white?'#fff':'#061c2f'};border:1px solid #69d8e777;box-shadow:0 20px 65px #0006;transform:perspective(1800px) rotateY(${options.tilt||0}deg) translateY(${22*(1-p)}px);opacity:${.45+.55*p}">${img(key,`position:absolute;inset:0;width:100%;height:100%;object-fit:${options.cover?'cover':'contain'};padding:${options.padding===undefined?12:options.padding}px;transform:scale(${scale})`)}<div style="position:absolute;top:${Math.max(0,clock*72)%(h+80)-40}px;left:0;right:0;height:2px;background:linear-gradient(90deg,transparent,#64f5d2aa,transparent);box-shadow:0 0 15px #64f5d244;pointer-events:none"></div>${options.overlay||''}</div>`);
};
const captionBar = (text,x,y,w) => pos(x,y,w,50,`<div class="small" style="font-size:23px;text-align:center;color:#a9e4e3">${text}</div>`);
const animatedBorder = (x,y,w,h,clock=t) => `<svg class="svg" viewBox="0 0 1920 1080"><rect x="${x}" y="${y}" width="${w}" height="${h}" rx="7" fill="none" stroke="${C.mint}" stroke-width="3" pathLength="400" stroke-dasharray="80 320" stroke-dashoffset="${-clock*100}" opacity=".8"/></svg>`;

// Exact installed Foxwen library evaluator plus sampled library animations.
const CWLibrary=(()=>{
/** Matches the deterministic renderer, including its polynomial easing contract. */
function evaluateMotionTrack(track, frame) {
    const keys = [...track.keyframes].sort((a, b) => a.frame - b.frame);
    if (!keys.length)
        return track.property.startsWith('scale') ||
            ['opacity', 'reveal'].includes(track.property)
            ? 1
            : 0;
    if (frame <= keys[0].frame)
        return keys[0].value;
    const right = keys.findIndex((key) => key.frame > frame);
    if (right < 0)
        return keys.at(-1).value;
    const a = keys[right - 1], b = keys[right];
    let t = (frame - a.frame) / (b.frame - a.frame);
    if (a.easing === 'ease-in')
        t *= t;
    else if (a.easing === 'ease-out')
        t = 1 - (1 - t) ** 2;
    else if (a.easing === 'ease-in-out')
        t = t < 0.5 ? 2 * t * t : 1 - (-2 * t + 2) ** 2 / 2;
    else if (a.easing === 'step')
        t = 0;
    return a.value + (b.value - a.value) * t;
}
function evaluateMotionValue(tracks, targetId, property, frame) {
    const track = tracks.find((item) => item.targetId === targetId && item.property === property);
    return track
        ? evaluateMotionTrack(track, frame)
        : property.startsWith('scale') || ['opacity', 'reveal'].includes(property)
            ? 1
            : 0;
