// Authored cooling-station illustration. Numbers and equipment motion illustrate control.
const fan = (cx,cy,r,clock,speed=1,color=C.mint) => `<g transform="translate(${cx} ${cy}) scale(1 .48)"><circle r="${r}" fill="#071626" stroke="#61baca" stroke-width="3"/><circle r="${r*.84}" fill="none" stroke="#336077" stroke-width="2"/>${[0,120,240].map(a=>`<path d="M0 0Q${r*.6} ${-r*.95} ${r*.76} ${-r*.2}Q${r*.8} ${r*.25} 0 0" fill="${color}" fill-opacity=".75" transform="rotate(${a+clock*speed*180})"/>`).join('')}<circle r="${r*.15}" fill="#d4fff5"/></g>`;
const rotor = (cx,cy,r,clock,speed=1) => `<g transform="translate(${cx} ${cy}) rotate(${clock*speed*160})"><circle r="${r}" fill="#0a2239" stroke="#64dcdf" stroke-width="3"/>${[0,60,120,180,240,300].map(a=>`<path d="M0 -5L${r*.7} -${r*.3}L${r*.6} ${r*.2}Z" fill="#5de4e4" transform="rotate(${a})"/>`).join('')}<circle r="${r*.17}" fill="#edffff"/></g>`;
const valve = (cx,cy,clock) => {
  const open=.3+.6*(.5+.5*Math.sin(clock*.9));
  return `<g transform="translate(${cx} ${cy})"><path d="M-25 -17L25 17V-17L-25 17Z" fill="#1b596e" stroke="#78e5e0" stroke-width="2"/><path d="M0 -18V-45" stroke="#7ed2e9" stroke-width="5"/><g transform="translate(0 -48) rotate(${open*100})"><ellipse rx="23" ry="9" fill="none" stroke="#7bf5d7" stroke-width="5"/><path d="M-22 0H22" stroke="#7bf5d7" stroke-width="3"/></g></g>`;
};
