// Original image and every explanatory overlay share one camera and coordinate plane.
const libraryValue = (tracks,property,at) => {
  const track=tracks.find(x=>x.property===property);
  return track?CWLibrary.evaluateMotionTrack(track,at):0;
};
const libraryMaterial = (kind,x,y,size,clock,id='') => {
  const frames=CWLibrary.materials[kind];
  const at=kind==='check'?Math.min(44,Math.max(0,Math.floor(clock*15))):Math.floor(Math.max(0,clock)*15)%45;
  const name=`cw-${kind}-${id||`${x}-${y}`}-`;
  const svg=frames[at].replaceAll('__lottie_element_',name);
  const spring=CWLibrary.evaluateMotionTrack(CWLibrary.motions.spring,Math.min(59,Math.max(0,clock*30)));
  const presetScale=libraryValue(CWLibrary.motions.preset,'scaleX',Math.min(24,Math.max(0,clock*30)));
  return pos(x,y,size,size,svg,`pointer-events:none;opacity:${kind==='pulse'?.28:1};transform:scale(${spring*presetScale})`);
};
const nativeProgress = (clock,duration) => {
  const track=CWLibrary.motions.flight.find(x=>x.property==='x');
