const lineChart = (clock=t,mode='load',progress=1) => {
  const values=Array.from({length:81},(_,i)=>{
    const x=i/80;
    const y=mode==='load'?140-62*Math.sin(x*10+clock*.75)-20*Math.sin(x*24-clock):mode==='stability'?130+(1-x)*70*Math.sin(x*35+clock*.6):60+x*105+8*Math.sin(x*12+clock*.5);
    return [x*720,y];
  });
  const count=Math.max(2,Math.ceil(progress*values.length)),pts=values.slice(0,count).map(([x,y])=>`${x},${y}`).join(' '),last=values[count-1];
  return `<svg viewBox="0 0 760 280" style="width:100%;height:100%"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#3de5c9" stop-opacity=".3"/><stop offset="1" stop-color="#3de5c9" stop-opacity="0"/></linearGradient></defs>${[45,95,145,195,245].map(y=>`<path d="M0 ${y}H740" stroke="#5a92b2" opacity=".2"/>`).join('')}<polygon points="0,260 ${pts} ${last[0]},260" fill="url(#chart-fill)"/><polyline points="${pts}" fill="none" stroke="#64f5d2" stroke-width="4"/><circle cx="${last[0]}" cy="${last[1]}" r="7" fill="#d3fff2"/><path d="M${clock*75%720} 20V260" stroke="#b7f7ff" stroke-dasharray="3 8" opacity=".5"/></svg>`;
};

// Motion belongs to each supplied picture: reveal, scan and highlight keep it legible.
const picturePanel = (key,x,y,w,h,options={}) => {
  const clock=options.clock===undefined?t:options.clock;
  const p=1-Math.pow(1-clamp(clock/.38),3);
  const scale=(options.scale||1)*(1+.012*Math.sin(Math.max(0,clock)*.65));
  const white=options.white!==false;
  return pos(x,y,w,h,`<div style="position:relative;width:100%;height:100%;overflow:hidden;background:${white?'#fff':'#061c2f'};border:1px solid #69d8e777;box-shadow:0 20px 65px #0006;transform:perspective(1800px) rotateY(${options.tilt||0}deg) translateY(${22*(1-p)}px);opacity:${.45+.55*p}">${img(key,`position:absolute;inset:0;width:100%;height:100%;object-fit:${options.cover?'cover':'contain'};padding:${options.padding===undefined?12:options.padding}px;transform:scale(${scale})`)}<div style="position:absolute;top:${Math.max(0,clock*72)%(h+80)-40}px;left:0;right:0;height:2px;background:linear-gradient(90deg,transparent,#64f5d2aa,transparent);box-shadow:0 0 15px #64f5d244;pointer-events:none"></div>${options.overlay||''}</div>`);
};
const captionBar = (text,x,y,w) => pos(x,y,w,50,`<div class="small" style="font-size:23px;text-align:center;color:#a9e4e3">${text}</div>`);
const animatedBorder = (x,y,w,h,clock=t) => `<svg class="svg" viewBox="0 0 1920 1080"><rect x="${x}" y="${y}" width="${w}" height="${h}" rx="7" fill="none" stroke="${C.mint}" stroke-width="3" pathLength="400" stroke-dasharray="80 320" stroke-dashoffset="${-clock*100}" opacity=".8"/></svg>`;

// Exact installed Foxwen library evaluator plus sampled library animations.
const CWLibrary=(()=>{
/** Matches the deterministic renderer, including its polynomial easing contract. */
function evaluateMotionTrack(track, frame) {
    const keys = [...track.keyframes].sort((a, b) => a.frame - b.frame);
    if (!keys.length)
        return track.property.startsWith('scale') ||
            ['opacity', 'reveal'].includes(track.property)
            ? 1
            : 0;
    if (frame <= keys[0].frame)
        return keys[0].value;
    const right = keys.findIndex((key) => key.frame > frame);
    if (right < 0)
        return keys.at(-1).value;
    const a = keys[right - 1], b = keys[right];
    let t = (frame - a.frame) / (b.frame - a.frame);
    if (a.easing === 'ease-in')
        t *= t;
    else if (a.easing === 'ease-out')
        t = 1 - (1 - t) ** 2;
    else if (a.easing === 'ease-in-out')
        t = t < 0.5 ? 2 * t * t : 1 - (-2 * t + 2) ** 2 / 2;
    else if (a.easing === 'step')
        t = 0;
    return a.value + (b.value - a.value) * t;
}
function evaluateMotionValue(tracks, targetId, property, frame) {
    const track = tracks.find((item) => item.targetId === targetId && item.property === property);
    return track
        ? evaluateMotionTrack(track, frame)
        : property.startsWith('scale') || ['opacity', 'reveal'].includes(property)
            ? 1
            : 0;
}

