// Original image and every explanatory overlay share one camera and coordinate plane.
const libraryValue = (tracks,property,at) => {
  const track=tracks.find(x=>x.property===property);
  return track?CWLibrary.evaluateMotionTrack(track,at):0;
};
const libraryMaterial = (kind,x,y,size,clock,id='') => {
  const frames=CWLibrary.materials[kind];
  const at=kind==='check'?Math.min(44,Math.max(0,Math.floor(clock*15))):Math.floor(Math.max(0,clock)*15)%45;
  const name=`cw-${kind}-${id||`${x}-${y}`}-`;
  const svg=frames[at].replaceAll('__lottie_element_',name);
  const spring=CWLibrary.evaluateMotionTrack(CWLibrary.motions.spring,Math.min(59,Math.max(0,clock*30)));
  const presetScale=libraryValue(CWLibrary.motions.preset,'scaleX',Math.min(24,Math.max(0,clock*30)));
  return pos(x,y,size,size,svg,`pointer-events:none;opacity:${kind==='pulse'?.28:1};transform:scale(${spring*presetScale})`);
};
const nativeProgress = (clock,duration) => {
  const track=CWLibrary.motions.flight.find(x=>x.property==='x');
  return CWLibrary.evaluateMotionTrack(track,clamp(clock/duration)*90);
};
const curvePoint = (points,u) => {
  const v=1-u;
  return [0,1].map(k=>v*v*v*points[0][k]+3*v*v*u*points[1][k]+3*v*u*u*points[2][k]+u*u*u*points[3][k]);
};
const originalFlow = (spec,clock) => {
  const [a,b,c,d]=spec.points,color=spec.color||'#0789c9';
  const path=`M${a.join(' ')}C${b.join(' ')} ${c.join(' ')} ${d.join(' ')}`;
  const age=clock-(spec.at||0),progress=nativeProgress(age,.6);
  if(age<0)return '';
  const span=spec.period||1.35;
  return `<path d="${path}" fill="none" stroke="${color}" stroke-width="5" stroke-opacity=".2"/><path d="${path}" fill="none" stroke="${color}" stroke-width="2.8" pathLength="100" stroke-dasharray="${progress*100} 100"/>${[0,.33,.66].map((offset,i)=>{
    const u=nativeProgress((Math.max(0,age)+offset*span)%span,span),p=curvePoint(spec.points,u),q=curvePoint(spec.points,Math.min(1,u+.02));
    const angle=Math.atan2(q[1]-p[1],q[0]-p[0])*180/Math.PI;
    return `<g transform="translate(${p[0]} ${p[1]}) rotate(${angle})"><path d="M-8 -4L0 0L-8 4" fill="none" stroke="${i?'#00aacd':'#096fb5'}" stroke-width="3.5" stroke-linecap="round"/><circle r="2.4" fill="#e9ffff"/></g>`;
  }).join('')}`;
};
const wholeBoard = (key,x,y,w,h,config={},clock=t) => {
  const vw=960,vh=config.height||435,offset=config.sourceY===undefined?100:config.sourceY,centerY=offset+vh/2,fit=Math.min(w/vw,h/vh);
  const regions=config.regions||[],duration=config.duration||D;
  const groups=config.groups||regions.map((_,i)=>[i]);
  const phase=Math.max(0,Math.min(groups.length-1,Math.floor(Math.max(0,clock-.6)/(Math.max(.1,duration-1.4)/Math.max(1,groups.length)))));
  const selectedRegions=groups[phase]||[];
  const active=selectedRegions[0]||0;
  const target=regions[active];
  const excursion=clock<1?0:clock>duration-1.3?1-smooth((clock-(duration-1.3))/1.15):1;
  const amount=config.zoom===undefined?.075:config.zoom;
  const zoom=1-amount+amount*.9*excursion;
  const focusX=target?target.rect[0]+target.rect[2]/2:480;
  const focusY=target?target.rect[1]+target.rect[3]/2:centerY;
  const aimX=480+(focusX-480)*.17*excursion,aimY=centerY+(focusY-centerY)*.17*excursion;
  const tx=Math.max(0,Math.min(vw*(1-zoom),480-aimX*zoom));
  const ty=Math.max(0,Math.min(vh*(1-zoom),vh/2-(aimY-offset)*zoom));
  const mappedRegions=regions.map((r,i)=>{
    const [rx,ry,rw,rh]=r.rect,selected=selectedRegions.includes(i);
    const spring=CWLibrary.evaluateMotionTrack(CWLibrary.motions.spring,Math.min(59,Math.max(0,(clock-(i*(duration-1.4)/Math.max(1,regions.length)))*30)));
    const pulse=.5+.5*Math.sin(clock*4+i);
    return `<g data-board-region="${i}" data-region-active="${selected}"><rect x="${rx-3}" y="${ry-3}" width="${rw+6}" height="${rh+6}" rx="5" fill="${selected?'#1da5db':'#46bede'}" fill-opacity="${selected?.045:0}" stroke="${selected?'#087eba':'#118ca5'}" stroke-opacity="${selected?.9:.14}" stroke-width="${selected?2.2*spring:1}"/><path d="M${rx-7} ${ry+16}v-23h23M${rx+rw-16} ${ry-7}h23v23M${rx+rw+7} ${ry+rh-16}v23h-23M${rx+16} ${ry+rh+7}h-23v-23" fill="none" stroke="#048ec4" stroke-width="3" opacity="${selected?.85:0}"/><circle cx="${rx+rw-2}" cy="${ry+2}" r="${3+3*pulse}" fill="#009db8" opacity="${selected?.85:0}"/>${selected&&config.numbers?`<g transform="translate(${rx+7} ${ry+8}) scale(${spring})"><circle r="12" fill="#0878ad"/><text y="4" text-anchor="middle" fill="white" font-size="11" font-family="sans-serif">${i+1}</text></g>`:''}</g>`;
  }).join('');
  const badge=target&&config.badge!==false?libraryMaterial(config.complete&&clock>duration-1.7?'check':'pulse',target.rect[0]+target.rect[2]-25,target.rect[1]-offset-23,48,clock,`${key}-${active}`):'';
  const overlay=`<svg data-motion-overlay="whole-diagram" viewBox="0 0 960 ${vh}" style="position:absolute;inset:0;width:960px;height:${vh}px;overflow:visible"><g transform="translate(0 ${-offset})">${mappedRegions}${(config.flows||[]).map(flow=>originalFlow(flow,clock)).join('')}${config.extra?config.extra(clock,active):''}</g></svg>`;
  return pos(x,y,w,h,`<div data-whole-board="${key}" data-animation-library="foxwen-native-lottie-mg" style="position:absolute;left:${(w-vw*fit)/2}px;top:${(h-vh*fit)/2}px;width:${vw*fit}px;height:${vh*fit}px;background:white;border:1px solid #66b8cc;box-shadow:0 22px 65px #0006;overflow:hidden"><div style="width:960px;height:${vh}px;transform-origin:0 0;transform:scale(${fit})"><div data-board-camera="${key}" style="position:relative;width:960px;height:${vh}px;transform-origin:0 0;transform:translate(${tx}px,${ty}px) scale(${zoom})">${img(key,`position:absolute;inset:0;width:960px;height:${vh}px;object-fit:fill`)}${overlay}${badge}</div></div></div>`);
};

